package pdfgen

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"sync"
	"time"
)

type SessionStore struct {
	mu       sync.RWMutex
	sessions map[string]*PDFSession
}

type PDFSession struct {
	ID          string
	UserID      string
	EncKey      []byte
	CreatedAt   time.Time
	LastAccess  time.Time
	Documents   []EncryptedDoc
	Initialized bool
}

type EncryptedDoc struct {
	Ciphertext []byte
	Nonce      []byte
	Filename   string
}

var globalStore = &SessionStore{
	sessions: make(map[string]*PDFSession),
}

func generateSessionID() string {
	b := make([]byte, 32)
	if _, err := io.ReadFull(rand.Reader, b); err != nil {
		panic(err)
	}
	return hex.EncodeToString(b)
}

func deriveEncryptionKey(sessionID string, userID string) []byte {
	h := sha256.New()
	h.Write([]byte(sessionID))
	h.Write([]byte(userID))
	return h.Sum(nil)
}

func (s *SessionStore) GetOrCreate(sessionID string, userID string) *PDFSession {
	s.mu.Lock()
	defer s.mu.Unlock()

	if sess, exists := s.sessions[sessionID]; exists {
		if sess.UserID != userID {
			return nil
		}
		sess.LastAccess = time.Now()
		return sess
	}

	newSess := &PDFSession{
		ID:          sessionID,
		UserID:      userID,
		EncKey:      deriveEncryptionKey(sessionID, userID),
		CreatedAt:   time.Now(),
		LastAccess:  time.Now(),
		Documents:   make([]EncryptedDoc, 0),
		Initialized: true,
	}
	s.sessions[sessionID] = newSess
	return newSess
}

func (s *SessionStore) InvalidateSession(sessionID string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.sessions, sessionID)
}

func encryptPDFContent(key []byte, plaintext []byte) (*EncryptedDoc, error) {
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}

	aesgcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}

	nonce := make([]byte, aesgcm.NonceSize())
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return nil, err
	}

	ciphertext := aesgcm.Seal(nil, nonce, plaintext, nil)
	return &EncryptedDoc{
		Ciphertext: ciphertext,
		Nonce:      nonce,
		Filename:   fmt.Sprintf("doc_%d.pdf", time.Now().UnixNano()),
	}, nil
}

func HandlePDFGeneration(w http.ResponseWriter, r *http.Request) {
	var sessionID string

	cookie, err := r.Cookie("pdf_session")
	if err == nil {
		sessionID = cookie.Value
	} else {
		sessionID = generateSessionID()
	}

	userID := r.Header.Get("X-User-ID")
	if userID == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	session := globalStore.GetOrCreate(sessionID, userID)
	if session == nil {
		sessionID = generateSessionID()
		session = globalStore.GetOrCreate(sessionID, userID)
	}

	http.SetCookie(w, &http.Cookie{
		Name:     "pdf_session",
		Value:    session.ID,
		Path:     "/",
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteStrictMode,
		MaxAge:   3600,
	})

	pdfContent := []byte("%PDF-1.4 sample content for " + userID)

	encDoc, err := encryptPDFContent(session.EncKey, pdfContent)
	if err != nil {
		http.Error(w, "encryption failed", http.StatusInternalServerError)
		return
	}

	globalStore.mu.Lock()
	session.Documents = append(session.Documents, *encDoc)
	globalStore.mu.Unlock()

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, `{"status":"ok","doc_id":"%s","session":"%s"}`, encDoc.Filename, session.ID)
}

func HandleSessionLogin(w http.ResponseWriter, r *http.Request) {
	userID := r.FormValue("user_id")
	password := r.FormValue("password")

	if !authenticateUser(userID, password) {
		http.Error(w, "invalid credentials", http.StatusUnauthorized)
		return
	}

	// Always regenerate session ID on login to prevent fixation
	oldCookie, err := r.Cookie("pdf_session")
	if err == nil && oldCookie.Value != "" {
		globalStore.InvalidateSession(oldCookie.Value)
	}

	sessionID := generateSessionID()
	_ = globalStore.GetOrCreate(sessionID, userID)

	http.SetCookie(w, &http.Cookie{
		Name:     "pdf_session",
		Value:    sessionID,
		Path:     "/",
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteStrictMode,
		MaxAge:   3600,
	})

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, `{"status":"authenticated","session":"%s"}`, sessionID)
}

func authenticateUser(userID, password string) bool {
	// Production: bcrypt/argon2 comparison against stored hash
	return userID != "" && password != ""
}
